from AlgorithmImports import *
import math


class PrivateLotStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.a_lot = 0
        self.b_lot = 0
        self.a_pending = False
        self.b_pending = False
        self.order_info = {}

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        if aapl_bar is not None:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_bars_present = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols)

        if (
            not self.IsWarmingUp
            and all_bars_present
            and self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        ):
            spy_close = spy_bar.Close
            spy_sma_value = self.spy_sma.Current.Value

            # Sells are evaluated before buys.
            if (
                self.a_lot > 0
                and not self.a_pending
                and self.previous_spy_close >= self.previous_spy_sma
                and spy_close < spy_sma_value
            ):
                self._submit_order("A", -self.a_lot)

            if (
                self.b_lot > 0
                and not self.b_pending
                and self.aapl_rsi.Current.Value > 60
            ):
                self._submit_order("B", -self.b_lot)

            if (
                self.a_lot == 0
                and not self.a_pending
                and self.previous_spy_close <= self.previous_spy_sma
                and spy_close > spy_sma_value
            ):
                quantity = int(
                    math.floor(
                        float(self.Portfolio.TotalPortfolioValue * 0.40 / spy_close)
                    )
                )
                if quantity > 0:
                    self._submit_order("A", quantity)

            if (
                self.b_lot == 0
                and not self.b_pending
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = int(math.floor(20_000 / float(aapl_bar.Close)))
                if quantity > 0:
                    self._submit_order("B", quantity)

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = (
                self.spy_sma.Current.Value if self.spy_sma.IsReady else None
            )

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

    def _submit_order(self, strategy, quantity):
        symbol = self.spy if strategy == "A" else self.aapl
        ticket = self.MarketOrder(symbol, quantity)
        self.order_info[ticket.OrderId] = strategy

        if strategy == "A":
            self.a_pending = True
        else:
            self.b_pending = True

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId not in self.order_info:
            return

        strategy = self.order_info[orderEvent.OrderId]

        if orderEvent.FillQuantity != 0:
            if strategy == "A":
                self.a_lot = max(0, self.a_lot + orderEvent.FillQuantity)
            else:
                self.b_lot = max(0, self.b_lot + orderEvent.FillQuantity)

        if orderEvent.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            self.order_info.pop(orderEvent.OrderId, None)

            if strategy == "A":
                self.a_pending = False
            else:
                self.b_pending = False
