class TwoSlotStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.last_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        # Keep market-state data current whenever the relevant bar is present.
        if self.spy in data.Bars:
            self.spy_closes.Add(float(data.Bars[self.spy].Close))

        if self.aapl in data.Bars:
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.last_aapl_close is not None:
                if aapl_close < self.last_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.last_aapl_close = aapl_close

        # Reflect any fills or corporate-action quantity adjustments.
        self.strategy_a_lot = max(0, int(self.Portfolio[self.spy].Quantity))
        self.strategy_b_lot = max(0, int(self.Portfolio[self.aapl].Quantity))

        # A missing daily bar for any subscribed ticker suppresses all rule evaluation.
        if any(symbol not in data.Bars for symbol in self.symbols.values()):
            return

        # Do not trade until all rule inputs are fully formed.
        if self.spy_closes.Count < 101 or not self.aapl_rsi.IsReady:
            return

        spy_close_today = float(self.spy_closes[0])
        spy_close_yesterday = float(self.spy_closes[1])

        spy_sma_today = sum(float(self.spy_closes[i]) for i in range(100)) / 100.0
        spy_sma_yesterday = (
            sum(float(self.spy_closes[i]) for i in range(1, 101)) / 100.0
        )

        spy_crossed_above = (
            spy_close_yesterday <= spy_sma_yesterday
            and spy_close_today > spy_sma_today
        )
        spy_crossed_below = (
            spy_close_yesterday >= spy_sma_yesterday
            and spy_close_today < spy_sma_today
        )

        # Evaluate sells before buys.
        if self.strategy_a_lot > 0 and spy_crossed_below:
            ticket = self.MarketOrder(self.spy, -self.strategy_a_lot)
            if ticket.Status != OrderStatus.Invalid:
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            ticket = self.MarketOrder(self.aapl, -self.strategy_b_lot)
            if ticket.Status != OrderStatus.Invalid:
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crossed_above:
            shares = int((0.40 * float(self.Portfolio.TotalPortfolioValue)) / spy_close_today)
            if shares > 0:
                ticket = self.MarketOrder(self.spy, shares)
                if ticket.Status != OrderStatus.Invalid:
                    self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            aapl_close = float(data.Bars[self.aapl].Close)
            available_cash = float(
                self.Portfolio.CashBook[self.AccountCurrency].Amount
            )

            if available_cash >= 20_000:
                shares = int(20_000 / aapl_close)
                if shares > 0:
                    ticket = self.MarketOrder(self.aapl, shares)
                    if ticket.Status != OrderStatus.Invalid:
                        self.strategy_b_lot = shares
